// FUNCTION: BFME2 0x000430C8 size=98 name=?clipCursorToClient@@YAXXZ evidence=N:ledger tier=B hypothesis:cohesion
void clipCursorToClient()
{
	RECT rect;
	GetClientRect((HWND)ApplicationHWnd, &rect);
	int width = rect.right - rect.left;
	int height = rect.bottom - rect.top;
	POINT point;
	point.x = rect.left;
	point.y = rect.top;
	ClientToScreen((HWND)ApplicationHWnd, &point);
	rect.left = point.x;
	rect.top = point.y;
	rect.right = point.x + width;
	rect.bottom = point.y + height;
	ClipCursor(&rect);
}

