void W3DDisplay::drawAnimStats()
{
	int color = -1;
	int acc = 3;
	for (int i = 0; i < 0x19; ++i)
	{
		if (m_animDebugStrings[i] == 0)
			continue;
		switch (i)
		{
		case 4:
			color = 0xFFFF9696;
			break;
		case 5:
			color = 0xFF64FF64;
			break;
		case 6:
			color = 0xFFA0A0FF;
			break;
		case 8:
			color = 0xFFFFFF00;
			break;
		case 10:
			color = 0xE164FF64;
			break;
		case 11:
			color = 0xE1FFFF00;
			break;
		case 13:
			color = 0xE164FF64;
			break;
		case 14:
			color = 0xD7FFFF00;
			break;
		case 16:
			color = 0xE164FF64;
			break;
		case 17:
			color = 0xCDFFFF00;
			break;
		case 19:
			color = 0xE164FF64;
			break;
		case 20:
			color = 0xC3FFFF00;
			break;
		case 22:
			color = 0xE164FF64;
			break;
		case 23:
			color = 0xB9FFFF00;
			break;
		}
		m_animDebugStrings[i]->setColors(color, 0xFF000000);
		m_animDebugStrings[i]->draw(3, acc, 1, 1);
		int width;
		int height;
		m_animDebugStrings[i]->getSize(&width, &height);
		acc += height;
	}
}

